#!/bin/bash
# Assemble host/rv32_divmod.S (no compressed insns) and write its words to host/rv32_stubs.inc,
# the table host/compiler.c appends to every --target rv32 blob. The generated file is checked
# in so building holyc-riscv never needs a RISC-V toolchain.
#   tools/gen_rv32_stubs.sh          regenerate
#   tools/gen_rv32_stubs.sh --check  exit 1 if the checked-in table is stale
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PREFIX="${RISCV_PREFIX:-riscv64-unknown-elf-}"
T="$(mktemp -d)"
trap 'rm -rf "$T"' EXIT
"${PREFIX}as" -march=rv32im -mabi=ilp32 -mno-relax -o "$T/s.o" "$ROOT/host/rv32_divmod.S"
"${PREFIX}ld" -m elf32lriscv -Ttext=0 -e rv32_divmod -o "$T/s.elf" "$T/s.o"   # resolve branch relocs
"${PREFIX}objcopy" -O binary -j .text "$T/s.elf" "$T/s.bin"
{
  echo "/* GENERATED by tools/gen_rv32_stubs.sh from host/rv32_divmod.S — do not edit. */"
  echo "static const uint32_t kRv32DivmodWords[] = {"
  od -An -v -t x4 "$T/s.bin" | tr -s ' ' '\n' | sed '/^$/d' | sed 's/^/  0x/; s/$/,/'
  echo "};"
} >"$T/out.inc"
if [ "${1:-}" = "--check" ]; then
  cmp -s "$T/out.inc" "$ROOT/host/rv32_stubs.inc" || { echo "host/rv32_stubs.inc is stale — run tools/gen_rv32_stubs.sh" >&2; exit 1; }
  exit 0
fi
cp "$T/out.inc" "$ROOT/host/rv32_stubs.inc"
echo "wrote host/rv32_stubs.inc ($(($(wc -c <"$T/s.bin") / 4)) words)"
